#!/usr/bin/env python3
"""Approved three-level subtitle intensity and Custom color indicator."""
from pathlib import Path
import hashlib,json
p=Path("gallery/Gallery-current.html")
raw=p.read_bytes()
assert len(raw)==6951780 and hashlib.sha256(raw).hexdigest()=="6d1aad0729347ff2f2078d35e931872e3eaf3f57924091203e4d777962be2c7c","STOP: GitHub baseline mismatch"
s=raw.decode("utf-8")
changes=json.loads("[[\"// Four intensity labels preserve existing light/normal/strong strengths, with a new Max.\",\"// Three intensity levels: Low and Medium unchanged, High uses the former Max.\"],[\"outline:{light:1,normal:3,strong:5,max:6},\\n  shadow:{light:1.5,normal:3,strong:6,max:10},\\n  box:{light:35,normal:65,strong:85,max:100}\",\"outline:{light:1,normal:3,strong:6},\\n  shadow:{light:1.5,normal:3,strong:10},\\n  box:{light:35,normal:65,strong:100}\"],[\"const SUBTITLE_EFFECT_LABELS=Object.freeze(['Low','Medium','High','Max']);\",\"const SUBTITLE_EFFECT_LABELS=Object.freeze(['Low','Medium','High']);\"],[\"v[presetKey]=['light','normal','strong','max'].includes(saved)?saved:subtitleNearestPreset(effect,v[key],v.size);\",\"v[presetKey]=saved==='max'?'strong':['light','normal','strong'].includes(saved)?saved:subtitleNearestPreset(effect,v[key],v.size);\"],[\"${['light','normal','strong','max'].map((value,i)=>\",\"${['light','normal','strong'].map((value,i)=>\"],[\".sf-subtitle-four{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px}\",\".sf-subtitle-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}\"],[\".sf-subtitle-four .sf-subtitle-choice\",\".sf-subtitle-three .sf-subtitle-choice\",2],[\"class=\\\"sf-subtitle-four\\\" role=\\\"group\\\"\",\"class=\\\"sf-subtitle-three\\\" role=\\\"group\\\"\"],[\".sf-subtitle-effects{min-width:0}\",\".sf-subtitle-custom-indicator{display:flex;align-items:center;justify-content:center;flex:none;width:14px;height:14px}\\n.sf-subtitle-custom-indicator [hidden]{display:none!important}\\n.sf-subtitle-custom-indicator .icon{width:14px;height:14px}\\n.sf-subtitle-effects{min-width:0}\"],[\"<span class=\\\"sf-subtitle-swatch subtitle-choice-swatch\\\" id=\\\"subtitle-custom-swatch\\\" style=\\\"background:${subtitlePrefs.customColor}\\\" aria-hidden=\\\"true\\\"></span>Custom\",\"<span class=\\\"sf-subtitle-custom-indicator\\\" aria-hidden=\\\"true\\\"><span id=\\\"subtitle-custom-palette\\\" ${subtitlePrefs.customColorSet?'hidden':''}>${icon('palette',14)}</span><span class=\\\"sf-subtitle-swatch subtitle-choice-swatch\\\" id=\\\"subtitle-custom-swatch\\\" style=\\\"background:${subtitlePrefs.customColor}\\\" ${subtitlePrefs.customColorSet?'':'hidden'}></span></span>Custom\"],[\"if(customSwatch)customSwatch.style.backgroundColor=subtitlePrefs.customColor;\",\"if(customSwatch){customSwatch.style.backgroundColor=subtitlePrefs.customColor;customSwatch.hidden=!subtitlePrefs.customColorSet;}\\n   const customPalette=settingsPage.querySelector('#subtitle-custom-palette');\\n   if(customPalette)customPalette.hidden=subtitlePrefs.customColorSet;\"]]")
for a,b,*count in changes:
    expected=count[0] if count else 1
    assert s.count(a)==expected,(a[:100],s.count(a),expected)
    s=s.replace(a,b)
p.write_bytes(s.encode("utf-8"))
print("Updated HTML:",len(p.read_bytes()),hashlib.sha256(p.read_bytes()).hexdigest())
tests=Path("gallery/tests/test_player_settings_regression.py")
t=tests.read_text(encoding="utf-8")
for a,b in json.loads("[[\"check(page.locator(\\\"[data-effect-strength]\\\").count()==4,\\\"Four effect intensity options\\\")\",\"check(page.locator(\\\"[data-effect-strength]\\\").count()==3,\\\"Three effect intensity options\\\")\"],[\"[\\\"Low\\\",\\\"Medium\\\",\\\"High\\\",\\\"Max\\\"]\",\"[\\\"Low\\\",\\\"Medium\\\",\\\"High\\\"]\"],[\"[(\\\"outline\\\",\\\"outline\\\",[1,3,5,6]),(\\\"shadow\\\",\\\"shadow\\\",[1.5,3,6,10]),(\\\"box\\\",\\\"boxOpacity\\\",[35,65,85,100])]\",\"[(\\\"outline\\\",\\\"outline\\\",[1,3,6]),(\\\"shadow\\\",\\\"shadow\\\",[1.5,3,10]),(\\\"box\\\",\\\"boxOpacity\\\",[35,65,100])]\"],[\"zip((\\\"light\\\",\\\"normal\\\",\\\"strong\\\",\\\"max\\\"),values)\",\"zip((\\\"light\\\",\\\"normal\\\",\\\"strong\\\"),values)\"],[\"page.locator(\\\".sf-subtitle-four\\\")\",\"page.locator(\\\".sf-subtitle-three\\\")\"],[\"page.locator(\\\"[data-effect-strength]\\\").count()==4,\\\"Four intensity buttons at \\\"\",\"page.locator(\\\"[data-effect-strength]\\\").count()==3,\\\"Three intensity buttons at \\\"\"]]"):
    assert t.count(a)==1,a
    t=t.replace(a,b)
a=" check(not errors,str(errors))\n page.close()\n for width in (1600,1280,800,440,340):"
assert t.count(a)==1
t=t.replace(a," # Distinguish unsaved Custom from a white preset; only Done stores a swatch.\n custom=page.locator('[data-subtitle-text-color=\"custom\"]')\n palette=page.locator(\"#subtitle-custom-palette\")\n swatch=page.locator(\"#subtitle-custom-swatch\")\n check(palette.is_visible() and not swatch.is_visible(),\"Unsaved Custom shows palette\")\n custom.click()\n page.locator(\".gallery-color-hex\").fill(\"#3366CC\")\n page.locator(\".gallery-color-close\").click()\n check(palette.is_visible() and not swatch.is_visible() and page.evaluate(\"subtitlePrefs.colorMode\")==\"white\",\"Cancelled custom change retains White and palette\")\n custom.click()\n page.locator(\".gallery-color-hex\").fill(\"#3366CC\")\n page.locator(\".gallery-color-done\").click()\n check(not palette.is_visible() and swatch.is_visible(),\"Confirmed Custom displays saved swatch\")\n check(page.evaluate(\"subtitlePrefs.customColorSet && subtitlePrefs.color==='#3366cc'\") and swatch.evaluate(\"(e)=>getComputedStyle(e).backgroundColor\")==\"rgb(51, 102, 204)\",\"Custom color and swatch match\")\n page.locator('[data-subtitle-text-color=\"yellow\"]').click()\n check(swatch.is_visible() and page.evaluate(\"subtitlePrefs.color\")==\"#ffe066\",\"Saved swatch remains visible when Yellow selected\")\n custom.click()\n check(page.evaluate(\"subtitlePrefs.color\")==\"#3366cc\" and page.locator(\".gallery-color-popover\").count()==0,\"Recall saved custom color without reopening editor\")\n custom.click()\n check(page.locator(\".gallery-color-popover\").is_visible(),\"Click selected Custom to edit\")\n page.locator(\".gallery-color-close\").click()\n page.locator('[data-subtitle-effect=\"none\"]').click()\n check(all(b.is_disabled() for b in page.locator(\"[data-effect-strength]\").all()),\"None disables intensity\")\n page.locator(\"#subtitle-reset\").click()\n check(palette.is_visible() and not swatch.is_visible(),\"Reset restores palette placeholder\")\n"+a)
a=' browser.close()'
assert t.count(a)==1
t=t.replace(a," # A routed in-memory page provides a real storage origin without network access.\n legacy=browser.new_page(viewport={\"width\":1200,\"height\":850})\n legacy.route(\"https://gallery-audit.invalid/**\",lambda route:route.fulfill(status=200,content_type=\"text/html\",body=html))\n legacy.goto(\"https://gallery-audit.invalid/\")\n legacy.evaluate(\"\"\"() => localStorage.setItem('gallery.subtitlePreferences', JSON.stringify({size:'normal',outlinePreset:'max',shadowPreset:'max',boxPreset:'max',colorMode:'custom',customColor:'#123456',customColorSet:true}))\"\"\")\n migrated=legacy.evaluate(\"readSubtitlePrefs()\")\n check([migrated[k] for k in (\"outlinePreset\",\"shadowPreset\",\"boxPreset\")]==[\"strong\"]*3,\"Legacy Max migrates to High\")\n check([migrated[k] for k in (\"outline\",\"shadow\",\"boxOpacity\")]==[5.5,10,100],\"Former Max strength preserved\")\n check(migrated[\"customColor\"]==\"#123456\" and migrated[\"customColorSet\"],\"Saved custom color survives migration\")\n legacy.close()\n"+a)
compile(t,str(tests),"exec")
tests.write_text(t,encoding="utf-8")
